// Package componentdeprecation connects generated component migration guidance to runtime notices.
package componentdeprecation // import "go.opentelemetry.io/collector/component/componentdeprecation"

import (
	"fmt"
	"sync"

	"go.uber.org/zap"
	"go.uber.org/zap/zapcore"
)

type (
	key    struct{ class, componentType, target string }
	notice struct {
		level   zapcore.Level
		message string
	}
)

var notices sync.Map

// MustRegister registers migration guidance generated by mdatagen. The identity
// is the canonical component type, or the Go import path for confmap factories.
// Conflicting declarations are reported only if the target is used.
func MustRegister(class, componentType, target string, level zapcore.Level, migration string) {
	if level < zap.DebugLevel || level > zap.ErrorLevel {
		panic(fmt.Sprintf("invalid deprecation notice level %s", level))
	}
	k := key{class, componentType, target}
	n := notice{level, "Deprecation notice for " + target + ": " + migration}
	if previous, _ := notices.LoadOrStore(k, n); previous != n {
		notices.Store(k, notice{zap.ErrorLevel, fmt.Sprintf("Conflicting deprecation notices for %s/%s: %s", class, componentType, target)})
	}
}

// Log writes the notice for this target and reports whether one was registered.
func Log(logger *zap.Logger, class, componentType, target string) bool {
	if write := Lookup(class, componentType, target); write != nil {
		write(logger)
		return true
	}
	return false
}

// Lookup returns the logger for a registered target, or nil if it has no notice.
func Lookup(class, componentType, target string) func(*zap.Logger) {
	value, ok := notices.Load(key{class, componentType, target})
	if !ok {
		return nil
	}
	n := value.(notice)
	return func(logger *zap.Logger) {
		if logger == nil {
			logger = zap.NewNop()
		}
		logger.Log(n.level, n.message)
	}
}
